-- ── story 5-1a: the email queue ──────────────────────────────────────────
-- Generated by drizzle-kit (the table and its two indexes — made IF NOT
-- EXISTS by hand, the 6-2a lint) and hand-amended below the marker: the
-- CHECKs, RLS and the post-migration probe (drizzle-kit is blind to all
-- three; `bun run db:generate` afterwards reports "No schema changes").
--
-- Additive only: one new table, written only by the mail module
-- (`queueEmailInTx` in the business transaction, the sender worker, the
-- cancels). No data statement — no pre-flight, no fail-fast. A new, empty
-- table: the index builds and CHECKs take no lock anyone waits on.
--
-- `sealed_secret` holds a send-time secret (an invite's raw token) sealed
-- under EMAIL_SEAL_KEY; `email_messages_secret_wipe_check` makes the wipe a
-- schema fact — a row may hold it only while `pending` or `sending`.
CREATE TABLE "email_messages" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"user_id" uuid,
	"template" text NOT NULL,
	"to_email" text NOT NULL,
	"params" jsonb NOT NULL,
	"sealed_secret" text,
	"status" text NOT NULL,
	"attempts" integer DEFAULT 0 NOT NULL,
	"next_attempt_at" timestamp with time zone NOT NULL,
	"provider_message_id" text,
	"error_code" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "email_messages_tenant_status_next_attempt_idx" ON "email_messages" USING btree ("tenant_id","status","next_attempt_at");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "email_messages_tenant_user_created_idx" ON "email_messages" USING btree ("tenant_id","user_id","created_at" DESC NULLS LAST);--> statement-breakpoint
-- ── hand-amended: the controlled vocabularies (IMPLEMENTATION-GUIDE §4) ────
-- `template` and `status` are NOT NULL, so their bare IN arms cannot pass on
-- a NULL. Pinned against the TS tuples (modules/mail/mail-rules.ts) by
-- test/mail.spec.ts.
ALTER TABLE "email_messages" ADD CONSTRAINT "email_messages_template_check" CHECK ("template" IN ('user-invite'));--> statement-breakpoint
ALTER TABLE "email_messages" ADD CONSTRAINT "email_messages_status_check" CHECK ("status" IN ('pending', 'sending', 'sent', 'failed', 'skipped', 'expired', 'cancelled'));--> statement-breakpoint
-- ── hand-amended: the wipe — a sealed secret only on a live row ───────────
ALTER TABLE "email_messages" ADD CONSTRAINT "email_messages_secret_wipe_check" CHECK ("sealed_secret" IS NULL OR "status" IN ('pending', 'sending'));--> statement-breakpoint
ALTER TABLE "email_messages" ADD CONSTRAINT "email_messages_attempts_check" CHECK ("attempts" >= 0);--> statement-breakpoint
-- ── hand-amended: RLS — the uniform tenant policy (the 0068 shape) ────────
ALTER TABLE "email_messages" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "email_messages_tenant_isolation" ON "email_messages"
	USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
	WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
-- ── the post-migration assertion (the 0064/0068 model) ────────────────────
-- The accepted shapes are inserted first and rolled back by a sentinel, so a
-- CHECK that refuses everything cannot pass. Each refused shape runs in its
-- own subtransaction and must be refused by `check_violation` ON THE NAMED
-- CONSTRAINT — a probe another CHECK happens to refuse proves nothing.
DO $$
DECLARE
	t uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
BEGIN
	-- (1) the accepted shapes: every status (a secret on both live ones, none
	-- on every final one), with and without a user.
	BEGIN
		INSERT INTO "email_messages" ("id","tenant_id","user_id","template","to_email","params","sealed_secret","status","attempts","next_attempt_at","provider_message_id","error_code")
		VALUES (gen_random_uuid(), t, gen_random_uuid(), 'user-invite', 'a@example.in', '{}', 'v1:k:i:t:c', 'pending', 0, now(), NULL, NULL),
		       (gen_random_uuid(), t, gen_random_uuid(), 'user-invite', 'a@example.in', '{}', 'v1:k:i:t:c', 'sending', 1, now(), NULL, NULL),
		       (gen_random_uuid(), t, gen_random_uuid(), 'user-invite', 'a@example.in', '{}', NULL, 'pending', 0, now(), NULL, NULL),
		       (gen_random_uuid(), t, NULL, 'user-invite', 'a@example.in', '{}', NULL, 'sent', 1, now(), 'ses-id', NULL),
		       (gen_random_uuid(), t, gen_random_uuid(), 'user-invite', 'a@example.in', '{}', NULL, 'failed', 5, now(), NULL, 'TooManyRequestsException'),
		       (gen_random_uuid(), t, gen_random_uuid(), 'user-invite', 'a@example.in', '{}', NULL, 'skipped', 0, now(), NULL, 'provider-off'),
		       (gen_random_uuid(), t, gen_random_uuid(), 'user-invite', 'a@example.in', '{}', NULL, 'expired', 0, now(), NULL, 'expired'),
		       (gen_random_uuid(), t, gen_random_uuid(), 'user-invite', 'a@example.in', '{}', NULL, 'cancelled', 0, now(), NULL, 'superseded');
		RAISE EXCEPTION USING ERRCODE = 'P0089', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation THEN
			RAISE EXCEPTION 'migration 0089: an accepted email message shape was refused.';
		WHEN SQLSTATE 'P0089' THEN
			NULL; -- the accepted shapes landed, and the sentinel rolled them back
	END;
	-- (2) the refused shapes, each by its named constraint.
	FOREACH probe IN ARRAY ARRAY[
		'unknown template',
		'unknown status',
		'a secret on a sent row',
		'a secret on a failed row',
		'a secret on a skipped row',
		'a secret on an expired row',
		'a secret on a cancelled row',
		'negative attempts'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'unknown template' THEN 'email_messages_template_check'
			WHEN 'unknown status' THEN 'email_messages_status_check'
			WHEN 'negative attempts' THEN 'email_messages_attempts_check'
			ELSE 'email_messages_secret_wipe_check'
		END;
		BEGIN
			CASE probe
				WHEN 'unknown template' THEN
					INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","next_attempt_at")
					VALUES (gen_random_uuid(), t, 'password-reset', 'a@example.in', '{}', 'pending', now());
				WHEN 'unknown status' THEN
					INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","next_attempt_at")
					VALUES (gen_random_uuid(), t, 'user-invite', 'a@example.in', '{}', 'queued', now());
				WHEN 'a secret on a sent row' THEN
					INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","sealed_secret","status","next_attempt_at")
					VALUES (gen_random_uuid(), t, 'user-invite', 'a@example.in', '{}', 'v1:k:i:t:c', 'sent', now());
				WHEN 'a secret on a failed row' THEN
					INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","sealed_secret","status","next_attempt_at")
					VALUES (gen_random_uuid(), t, 'user-invite', 'a@example.in', '{}', 'v1:k:i:t:c', 'failed', now());
				WHEN 'a secret on a skipped row' THEN
					INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","sealed_secret","status","next_attempt_at")
					VALUES (gen_random_uuid(), t, 'user-invite', 'a@example.in', '{}', 'v1:k:i:t:c', 'skipped', now());
				WHEN 'a secret on an expired row' THEN
					INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","sealed_secret","status","next_attempt_at")
					VALUES (gen_random_uuid(), t, 'user-invite', 'a@example.in', '{}', 'v1:k:i:t:c', 'expired', now());
				WHEN 'a secret on a cancelled row' THEN
					INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","sealed_secret","status","next_attempt_at")
					VALUES (gen_random_uuid(), t, 'user-invite', 'a@example.in', '{}', 'v1:k:i:t:c', 'cancelled', now());
				WHEN 'negative attempts' THEN
					INSERT INTO "email_messages" ("id","tenant_id","template","to_email","params","status","attempts","next_attempt_at")
					VALUES (gen_random_uuid(), t, 'user-invite', 'a@example.in', '{}', 'pending', -1, now());
			END CASE;
		EXCEPTION WHEN check_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS NULL THEN
			RAISE EXCEPTION 'migration 0089: the CHECK probe "%" was not refused.', probe;
		END IF;
		IF refused_by <> expected THEN
			RAISE EXCEPTION 'migration 0089: the CHECK probe "%" was refused by % — expected %.', probe, refused_by, expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "email_messages" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0089: a CHECK probe row survived.';
	END IF;
END $$;
